WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (698::BIGINT, 'Me gustó como Beto dio este curso, a pesar de que habían pasado años desde que le tocó Arqui 2. A este punto, lo más seguro es que ya llevó Betocreditos, entonces ya debe saber como usualmente trabaja él con exámenes y proyectos. Bonito curso la verdad, bastante interesante'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2026-07-18T00:00:00+00:00'::TIMESTAMPTZ, '8979fa891aa900957ef694d8aa64b3a315b29656d870a20f8693bbcc1e1bf5d7'::TEXT, ARRAY[2982]::BIGINT[]),
    (698::BIGINT, 'El curso es difícil, los exámenes son una masacre, pero el profe en general es bastante bueno explicando. Con que practique bastante con los exámenes viejos para el examen y consiga un buen grupo para los proyectos, se pasa.'::TEXT, 2.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Pocos exámenes', 'Muchos proyectos grupales']::TEXT[], '2025-12-15T00:00:00+00:00'::TIMESTAMPTZ, '44c9b2217a0535fcf34e229550d926462a31257d256af5127eb8ea0d9975137a'::TEXT, ARRAY[2975]::BIGINT[]),
    (698::BIGINT, 'El curso en sí al ser un Taller depende totalmente de usted y no del profe, ahora bien, Beto no califica duro y los proyectos que deja son super realizables, como recomendación personal, consiga un grupo de trabajo que conozca y si es necesario vayan en horario de clases a trabajar x si ocupan ayuda'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Muchos proyectos grupales']::TEXT[], '2025-12-09T00:00:00+00:00'::TIMESTAMPTZ, 'a47346c125be64875c349cb2ddc3053865ab54d5b727d5335f2c63d2841749fd'::TEXT, ARRAY[2979]::BIGINT[]),
    (698::BIGINT, 'Grande Beto. El curso por si solo no es tan dificil. Como siempre, algo sale mal a la hora de montar circuitos y probarlos, pero los proyectos no son imposibles. Y el profe siembre brinda ayuda, y no califica duro'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2025-12-03T00:00:00+00:00'::TIMESTAMPTZ, '32cb3ee2750cc1f8b80934454f56f5ee3e7d8f05b6a3c0ca8ca8626c1da1e47d'::TEXT, ARRAY[2979]::BIGINT[]),
    (698::BIGINT, 'Buen profe, pero la materia del curso no ayuda mucho, sus presentaciones pueden asustar con la exagerada información técnica y compleja, pero en la parte práctica es bastante sencillo. Si la mayoría de la clase va mal, deja asignaciones para puntos extras'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Aspectos de calificación claros']::TEXT[], '2025-12-02T00:00:00+00:00'::TIMESTAMPTZ, 'cc3e347574084e72b238b9327162fb4e83250b46e62bb739224d8389b6e4085b'::TEXT, ARRAY[2975]::BIGINT[]),
    (698::BIGINT, 'El profe es chill, solo que se suele desviarse durante sus clases y algunas cosas no quedan lo suficientemente claras. El curso es fácil, aunque los proyectos pueden ser abusados, aunque ayuda bastante con ellos'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2025-07-19T00:00:00+00:00'::TIMESTAMPTZ, 'c290732749910c90b9a4c473c6a14d8c0c9fa42657b1bf9048920628812ed973'::TEXT, ARRAY[2961]::BIGINT[]),
    (698::BIGINT, 'El profe es muy buena nota, pero a veces se enreda un poco cuando está explicando. En parte también es culpa de la materia (demasiado compleja). Hay que practicar mucho y preferiblemente verse las clases de Barboza (electro) para pasar más fácil.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2025-02-09T00:00:00+00:00'::TIMESTAMPTZ, '3bb412a31033db94c11cf7c0fe29fe64f6fdfb3749d5417797864733f3c377b2'::TEXT, ARRAY[2975]::BIGINT[]),
    (698::BIGINT, 'De los mejores profes de la carrera. Los exámenes no son tan feos, nunca entra algo que el profe no explicó. Hasta da pistas de las posibles preguntas. Los proyectos son un toque difíciles, pero el profe siempre está dispuesto a resolver dudas y evaluar el progreso.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2025-02-08T00:00:00+00:00'::TIMESTAMPTZ, '4ea27654b8c1e04a7b4f56a52673a08e2f64cc58a91fc33d8759bebc1a16d016'::TEXT, ARRAY[2969]::BIGINT[]),
    (698::BIGINT, 'Como profesor va demasiado rápido, y creo que es importante entender la materia antes de hacer un proyecto. No me convence el método de proyectos sin teoría. Sin embargo, es una gran persona y ser humano; si mejorara eso, sería excelente.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2024-11-04T00:00:00+00:00'::TIMESTAMPTZ, '0260a172019068a0ab6e1eb5a14e5d49bf5baa59b32d907723cc486557817728'::TEXT, ARRAY[2973]::BIGINT[]),
    (698::BIGINT, 'Muy buen profe, sin embargo, el curso es muy pesado y requiere de algún cambio para poder suministrar la materia de una mejor forma para maximizar el aprendizaje.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Muchos proyectos grupales']::TEXT[], '2024-10-23T00:00:00+00:00'::TIMESTAMPTZ, '8e615f012d5c72759110919425d14b131e886daef1d7e56e9dfaa96cc7d735b8'::TEXT, ARRAY[2974]::BIGINT[]),
    (698::BIGINT, 'El profe cae súper bien y se preocupa bastante para que todos entiendan, el profe ayuda bastante y califica de manera justa y ve la situación de cada estudiante para ayudarle. Súper recomendado, en si el curso es bastante interesante'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2024-06-20T00:00:00+00:00'::TIMESTAMPTZ, '24309472a72c411492d8ae1a3b4fb90a4daf0716714242db78f20af68562326f'::TEXT, ARRAY[2961]::BIGINT[]),
    (698::BIGINT, 'En sí el profe es muy pura vida, pero las evaluaciones suelen ser un poco tediosas. De igual manera, el curso puede llegar a ser un poco complicado de explicar y de evaluar.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Brinda apoyo', 'Muchos proyectos grupales']::TEXT[], '2024-06-12T00:00:00+00:00'::TIMESTAMPTZ, '66c4604c4b5d156e7e31125452a45da25ec5af5f6357dd00bff93959ee7e7b92'::TEXT, ARRAY[2969]::BIGINT[]),
    (698::BIGINT, 'Dios bendiga a Beto Deidad. Excelente profe, de los mejores que hay en CE. Gracias a él, Señales pasa de ser imposible a dificil pero pasable. Exámenes y proyectos son rudos, pero ayuda bastante con las consultas, y deja tareas y talleres que sirven de avance para los proyectos. Matricule sin duda'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Exámenes retadores']::TEXT[], '2024-06-12T00:00:00+00:00'::TIMESTAMPTZ, '8c0d65e76e2b9790798f66991b2fc80e3aed64b0c57041837d747f0a57ac413a'::TEXT, ARRAY[2975]::BIGINT[]),
    (698::BIGINT, 'Excelente profesor, no piense dos veces matricular cursos con él, sin embargo los cursos que da usualmente son difíciles y algunos nuevos como señales todavía ocupan refinarse por lo que cuesta entenderle bien la materia, pero califica justo y siempre apoya bastante.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Da buena retroalimentación']::TEXT[], '2023-12-05T00:00:00+00:00'::TIMESTAMPTZ, 'eace1babce7d2bc50ac42018f6167790581d484972372ddb881fd5a82d97b057'::TEXT, ARRAY[2975]::BIGINT[]),
    (698::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2023-09-13T00:00:00+00:00'::TIMESTAMPTZ, 'a796bd41622aad8dc814f1d55b8e219916eb745b0429a37b9093d8e42e3b4822'::TEXT, ARRAY[2973]::BIGINT[]),
    (698::BIGINT, 'El curso en sí se las trae, la materia de los exámenes es complicada, pero si usted se apoya en las prácticas y en las horas de consulta sale bien. El profe de los mejores de CE, es demasiado amable, comprensivo y respetuoso. Al pedirle ayuda siempre lo guía a uno, valora mucho el interés.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchas tareas', 'Exámenes retadores']::TEXT[], '2023-08-30T00:00:00+00:00'::TIMESTAMPTZ, '1d9b39520821a5907c842c44441a424cc1f7fe491b31daa35f1e0111d1e03516'::TEXT, ARRAY[2973]::BIGINT[]),
    (698::BIGINT, 'El profe es super buena gente. Ayuda, es respetuoso, crea un ambiente de confianza. Por otro lado, la materia del curso y la forma de evaluar en los exámenes son completamente diferentes. Podría explicar mejor. Además, la redacción de las asignaciones es bastante confusa'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-16T00:00:00+00:00'::TIMESTAMPTZ, 'e0cbfc2bf0f7fa650d395dffe82dfb8266e89f23f874729de675b2c92c334b53'::TEXT, ARRAY[2973]::BIGINT[]),
    (698::BIGINT, 'El profe es super pura vida y siempre anuente a ayudar a los estudiantes en lo que pueda. Los proyectos bastantes accesibles para verano. Lo recomiendo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2023-01-30T00:00:00+00:00'::TIMESTAMPTZ, 'cb9561f28e6ca90dfd9c3ca4a5992847ca79105465ca8cda8a5c0d6d67af3389'::TEXT, ARRAY[2980]::BIGINT[]),
    (698::BIGINT, 'No sabe calcular la dificultad acorde a las horas por credito. Deja multiples asignaciones al mismo tiempo. Los proyectos son muy largos y dificiles. Lo que explica en clase es insuficiente para resolver los examenes. Algunas veces penaliza mas de una vez por el mismo rubro.'::TEXT, 2.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2022-09-21T00:00:00+00:00'::TIMESTAMPTZ, '6560a69722c7db042bbbff9fe4b5a860dc3b66bf0058d3d3b68543f7686eefcb'::TEXT, ARRAY[2973, 2982]::BIGINT[]),
    (698::BIGINT, 'Buen profe, muy pura vida. El curso quita mucho tiempo para valer solo 1 crédito pero el profe es muy comprensivo entonces basta con ser responsable e ir al día para pasar el curso sin problema.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, '4997e10dfc7c3d5fb7688cf5a4755b23e4dd682a1e6f5b899d0581feb1b10e2e'::TEXT, ARRAY[2968]::BIGINT[]),
    (698::BIGINT, 'Es muy buena gente, me hubiera gustado que el profe explicara más que hay que hacer, pero en parte eso es problema de como se dan las clases. No me parece mal profe, aunque podría explicar más, lo recomiendo.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-16T00:00:00+00:00'::TIMESTAMPTZ, 'a33c361f60d858c4e5ec29e8da7cb1c167b6a54742296a9cf1ff682c9a6daa9a'::TEXT, ARRAY[2968]::BIGINT[]),
    (698::BIGINT, 'Muy buena persona, sin embargo como profe se queda un poco atrás. Muchas evaluaciones por lo que quita mucho tiempo. Se equivoca en los enunciados de los talleres y proyectos. Los exámenes son difíciles.'::TEXT, 2.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Brinda apoyo']::TEXT[], '2021-06-15T00:00:00+00:00'::TIMESTAMPTZ, '45f066abd8b1e74286c0af892fd37166fe3a55d79248ad4efa234ae0186f8cb2'::TEXT, ARRAY[2973]::BIGINT[]),
    (698::BIGINT, 'Ayuda muchísimo y es muy buena persona. Los enunciados no siempre son claros, pero es muy accesible y califica justo. En metodología virtual conlleva mucha documentación, pero se aprende.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-07T00:00:00+00:00'::TIMESTAMPTZ, 'bd1d93b5e526712769d50f923ddea3b8af03be895f5d0ea39626b25e32eda2cb'::TEXT, ARRAY[2969, 2973, 2982]::BIGINT[]),
    (698::BIGINT, 'Buen profe, deja muuuchos trabajos y mucha documentación, se aprende.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Muchos proyectos grupales']::TEXT[], '2021-02-04T00:00:00+00:00'::TIMESTAMPTZ, '70b5a8df7dc825a7720a4684f4c2491c8932e2f0bc50780f848a491f9bf729d8'::TEXT, ARRAY[2982]::BIGINT[]),
    (698::BIGINT, 'Es un buen profesor, muy dedicado y da ayuda al que se la solicite. Procura hacer la clase interactiva. Sin embargo, a mí me cuesta un poco prestarle atención. Los proyectos son más difíciles que los exámenes, aunque valen lo mismo. La redacción de los enunciados suele tener errores y ambigüedades.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-10-09T00:00:00+00:00'::TIMESTAMPTZ, '36b562db652ebadfd977baa26a70faa3213263c49dd15bf345fe3828a99018c7'::TEXT, ARRAY[2973]::BIGINT[]),
    (698::BIGINT, 'Clases de 40 min-1 h. Explica bastante claro y los proyectos son de dificultad razonable, incluso fáciles si tiene un buen equipo. El último proyecto con Gem5 y PARSEC estuvo algo aburrido. En las revisiones le da más peso a cómo aplico los conceptos vistos en clases y le da mucha retroalimentación.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-10-07T00:00:00+00:00'::TIMESTAMPTZ, 'f6c66c3303132b1eb2d7bf0ff0c1a69ac53b70a06e03d1e18dcfa4ee2fc35fa0'::TEXT, ARRAY[2973]::BIGINT[]),
    (698::BIGINT, 'Muy buen profe. Las defensas de proyecto no se enfocan tanto en funcionalidad, si no en dominio de la materia'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Respetado por los estudiantes']::TEXT[], '2020-08-17T00:00:00+00:00'::TIMESTAMPTZ, '359f006c004617423340f3ab305d8a43f438a5af3cc73a4d460c707a65ddf843'::TEXT, ARRAY[2973]::BIGINT[]),
    (698::BIGINT, 'Las clases son aburridas en general, pero el profe es bastante bueno. Los proyectos tienen su dificultad, pero para la defensa lo que él quiere ver es como se aplicaron los conceptos de la clase al proyecto y no se enfoca al 100% en la funcionalidad, entonces ayuda bastante. Recomendado.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Brinda apoyo']::TEXT[], '2020-08-16T00:00:00+00:00'::TIMESTAMPTZ, '13429577ea89a0bc891f81f65ed651e2e8f2a8c7f9ecaaf9633bd8da3d838f73'::TEXT, ARRAY[2973]::BIGINT[]),
    (698::BIGINT, 'Explica muy bien, las clases son entretenidas. Los proyectos son de dificultad razonable y en la revision se tiene una dinamica diferente que le ayuda a aprender mas a uno. Los examenes son regulares y califica justo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria', 'Respetado por los estudiantes']::TEXT[], '2019-11-24T00:00:00+00:00'::TIMESTAMPTZ, 'cdd1f3253c56e08ff3328752773789ac26faa164720147743bdbb5e8e3c6b896'::TEXT, ARRAY[2973]::BIGINT[]),
    (698::BIGINT, 'La verdad un muy buen profesor. Las clases son de 40 minutos. Ayuda mucho en consulta y las revisiones poseen una dinámica muy interesante. Le interesa mucho el feedback y opinión de los estudiantes.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2019-11-24T00:00:00+00:00'::TIMESTAMPTZ, '0d7bf9e855434f053a34e8666bc7f34d2260c15b0f7dc957c58f2f9d570999b7'::TEXT, ARRAY[2973]::BIGINT[]),
    (698::BIGINT, 'Explica muy bien, se preocupa porque el estudiante aprenda, es claro a la hora de calificar y da muy buen feedback sobre los trabajos calificados.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2019-09-24T00:00:00+00:00'::TIMESTAMPTZ, '3e4029a22017d2eb05abf24d9f83f36ca3b07a1121d784578eac6d4c6817b013'::TEXT, ARRAY[2968]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
